  {
    name: "Empty pair opens menu with add actions",
    input: "drag from Question node dot to Claim node (no relation defined for Question-Claim)",
    expected: "menu opens with Add existing… / Create new, no + button, pending arrow kept and bound, no warning toast",
    run: async (ctx) => {
      await prepare(ctx);
      const pts = await dragRelation(ctx, Q, C);
      return { dots: pts.dotCount, ...(await observe(ctx)) };
