    expect: (o) => ({
      pass: o.menuOpen && same(o.menuItems, ADD) && !o.plus && o.arrowCount === 1 && bothBound(o) && o.toasts.length === 0,
      actual: `menu=${o.menuOpen} items=${o.menuItems.join("/")} plus=${!!o.plus} arrows=${o.arrowCount} bindings=${o.arrow?.bindings.length} toasts=[${o.toasts}] menu=${JSON.stringify(o.menuRect)}`,
    }),
  },
