      pass: !o.menuOpen && o.arrowCount === 0 && o.toasts.includes("Both nodes need a node type to create a relation"),
      actual: `menu=${o.menuOpen} arrows=${o.arrowCount} toasts=[${o.toasts}]`,
    }),
    teardown: ({ client, json }) =>
      client.evaluate(`window.__dgEd.updateShape({ id: ${json(Q)}, type: "discourse-node", props: { nodeTypeId: "node_vqZxAvvuf-AN9E5Y4kH-F" } }); return true;`),
  },
  {
    name: "Style panel does not cover the menu's + button",
    input: "Evidence to Claim with the pair near the right edge (default camera); hit-test the + button center",
    expected: "elementFromPoint at the + center is the + button (or its icon)",
    run: async (ctx) => {
      await prepare(ctx);
      await dragRelation(ctx, E, C);
      return ctx.client.evaluate(`
        const btn = document.querySelector('[aria-label="Add relation type"]');
        if (!btn) return { found: false };
        const r = btn.getBoundingClientRect();
        const hit = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
        const p = document.querySelector(".tlui-style-panel")?.getBoundingClientRect();
