    st.discourseRelations = st.discourseRelations.filter((r) => !((r.sourceId === ${ctx.json(s)} && r.destinationId === ${ctx.json(t)}) || (r.sourceId === ${ctx.json(t)} && r.destinationId === ${ctx.json(s)})));
