// Tidy fixture, clean in-memory settings (restored in teardown), hide Obsidian notices.
const docsPrepare = async (ctx) => {
  await ctx.client.evaluate(`app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse(); return true;`);
  await prepare(ctx);
  await ctx.client.evaluate(`const st = ${P(ctx)}.settings;
    const keep = new Set(["supports", "opposes", "informs", "derived from"]);
    st.relationTypes = st.relationTypes.filter((r) => keep.has(r.label));
    const ids = new Set(st.relationTypes.map((r) => r.id));
    const q = ${ctx.json("node_vqZxAvvuf-AN9E5Y4kH-F")}, c = ${ctx.json("node_bqu6_78DrVvuDnqmc6QzS")};
