      const picker = await ctx.client.evaluate(`const header = [...document.querySelectorAll("span")].find((s) => s.textContent.trim().toLowerCase() === "relation type");
        return [...header.closest(".pointer-events-auto").querySelectorAll("button")].map((b) => b.textContent.trim());`);
      await shot(ctx, "relation-type-add-existing.png");
      await clickButton(ctx, "informs / is informed by");
      await sleep(700);
      const o = await observe(ctx);
      await shot(ctx, "relation-type-added.png");
      return { picker, ...o };
    },
    expect: (o) => ({ pass: o.picker.some((p) => p.startsWith("informs")) && o.menuItems.includes("informs") && o.toasts.length > 0, actual: `picker=[${o.picker}] menu=[${o.menuItems}] toasts=[${o.toasts}]` }),
    teardown: restore,
  },
  {
    name: "Create new flow (GIF frames)",
    input: `drag Claim → Question; Create new; "${LABEL}" / "${COMPLEMENT}" / Blue; Continue; click ${LABEL}`,
    expected: "dialog, both toasts, new type listed, arrow labelled",
    setup: snapshot,
    run: async (ctx) => {
      await docsPrepare(ctx);
      const fr = recorder("create-flow");
      fr.ctx = ctx;
      await fr.add("start", 1.2);
