S=/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/e0553a10-9150-443e-8d24-56cd52b45497/scratchpad/cdp; { sed -n '1,129p' $S/docs.mjs | sed 's#^// ENG-2360 docs screenshots.*#// ENG-2360 docs GIFs at human speed: visible cursor, eased moves, per-character typing.#'; sed -n '/^\/\/ Frame recorder/,/^};$/p' $S/docs.mjs; cat <<'EOF'

const ARROW = `<svg xmlns="http://www.w3.org/2000/svg" width="22" height="28" viewBox="0 0 22 28"><path d="M2 2 L2 22 L7.5 17 L11 26 L14.5 24.5 L11 15.8 L18.5 15.8 Z" fill="black" stroke="white" stroke-width="1.6" stroke-linejoin="round"/></svg>`;

// Screenshots omit the OS cursor; draw one so viewers can follow the pointer.
const cursorAt = (ctx, p) =>
  ctx.client.evaluate(`let c = document.getElementById("dg-doc-cursor");
    if (!c) { c = document.createElement("div"); c.id = "dg-doc-cursor";
      c.style.cssText = "position:fixed;z-index:2147483647;pointer-events:none;left:0;top:0;width:22px;height:28px;";
      c.innerHTML = ${ctx.json(ARROW)}; document.body.appendChild(c); }
    c.style.transform = "translate(" + ${p.x} + "px," + ${p.y} + "px)"; return true;`);
const removeCursor = (ctx) => ctx.client.evaluate(`document.getElementById("dg-doc-cursor")?.remove(); return true;`);

const FRAME = 0.06; // seconds per motion frame
const ease = (t) => (t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2);

// A pointer that moves, clicks, drags and types at human pace, recording frames as it goes.
const human = (ctx, fr, start) => {
  let pos = start;
  const send = (type, p, extra = {}) =>
    ctx.client.send("Input.dispatchMouseEvent", { type, x: p.x, y: p.y, button: "left", clickCount: 1, ...extra });
  const moveTo = async (to, ms = 600, buttons = 0) => {
    const steps = Math.max(2, Math.round(ms / 1000 / FRAME));
    const from = pos;
    for (let i = 1; i <= steps; i++) {
      const t = ease(i / steps);
      pos = { x: from.x + (to.x - from.x) * t, y: from.y + (to.y - from.y) * t };
      await send("mouseMoved", pos, buttons ? { buttons: 1 } : { button: "none" });
      await cursorAt(ctx, pos);
      await fr.add("move", FRAME);
    }
  };
  return {
    get pos() { return pos; },
    moveTo,
    async hold(sec) { await cursorAt(ctx, pos); await fr.add("hold", sec); },
    async click(to, { ms = 600, after = 0.5 } = {}) {
      await moveTo(to, ms);
      await fr.add("aim", 0.2);
      await send("mousePressed", pos, { buttons: 1 });
      await send("mouseReleased", pos);
      await sleep(350);
      await cursorAt(ctx, pos);
      await fr.add("clicked", after);
    },
    async drag(from, to, ms = 1100) {
      await moveTo(from, 350);
      await fr.add("aim", 0.25);
      await send("mousePressed", pos, { buttons: 1 });
      await moveTo(to, ms, 1);
      await send("mouseReleased", pos);
      await sleep(500);
    },
    async type(text, perChar = 0.11) {
      for (const ch of text) {
        await ctx.client.typeText(ch);
        await fr.add("type", perChar);
      }
    },
  };
};

const shapeCenter = (ctx, id) =>
  ctx.client.evaluate(`const ed = window.__dgEd; const b = ed.getShapePageBounds(${ctx.json(id)}); return ed.pageToScreen({ x: b.midX, y: b.midY });`);
const dotToward = (ctx, to) =>
  ctx.client.evaluate(`const ed = window.__dgEd; const b = ed.getShapePageBounds(${ctx.json(to)});
    const t = ed.pageToScreen({ x: b.midX, y: b.midY });
    const dots = [...ed.getContainer().querySelectorAll(".cursor-crosshair")].map((d) => { const r = d.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; });
    dots.sort((a, c) => Math.hypot(a.x - t.x, a.y - t.y) - Math.hypot(c.x - t.x, c.y - t.y));
    return dots[0] ?? null;`);
const MENU = `(() => { const h = [...document.querySelectorAll("span")].find((s) => s.textContent.trim().toLowerCase() === "relation type"); return h?.closest(".pointer-events-auto"); })()`;
const menuButton = (ctx, label) =>
  centerOf(ctx, label === "+" ? `return ${MENU}?.querySelector('[aria-label="Add relation type"]');`
    : `return [...(${MENU}?.querySelectorAll("button") ?? [])].find((b) => b.textContent.trim() === ${ctx.json(label)});`);
const dialogEl = (ctx, js) => centerOf(ctx, js);

// Rest the cursor below the cards, then select `from` and drag from its nearest dot onto `to`.
const startAndDrag = async (ctx, name, from, to) => {
  await docsPrepare(ctx);
  const fr = recorder(name);
  fr.ctx = ctx;
  const r = await clipRect(ctx);
  const h = human(ctx, fr, { x: r.x + r.width * 0.45, y: r.y + r.height * 0.62 });
  await h.hold(1.0);
  await h.click(await shapeCenter(ctx, from), { ms: 700, after: 0.6 });
  const dot = await dotToward(ctx, to);
  if (!dot) throw new Error("no drag dots");
  await h.drag(dot, await shapeCenter(ctx, to));
  return { fr, h };
};

const finish = async (ctx, fr, holdSec = 3) => {
  await removeCursor(ctx);
  await fr.add("end", holdSec);
  return fr.done();
};

const LABEL = "addresses";
const COMPLEMENT = "is addressed by";

export default [
  {
    name: "GIF: empty relation type menu",
    input: "select Claim, drag dot onto Question (no types for the pair)",
    expected: "menu with Add existing… / Create new",
    setup: snapshot,
    run: async (ctx) => {
      const { fr, h } = await startAndDrag(ctx, "gif-empty", C, Q);
      await h.moveTo(await menuButton(ctx, "Add existing…"), 500);
      await h.hold(1.2);
      await h.moveTo(await menuButton(ctx, "Create new"), 350);
      await h.hold(1.4);
      const o = await observe(ctx);
      return { frames: await finish(ctx, fr, 2), items: o.menuItems };
    },
    expect: (o) => ({ pass: o.items.join("|") === "Add existing…|Create new", actual: `frames=${o.frames} items=${o.items}` }),
    teardown: async (ctx, s) => { await removeCursor(ctx); await restore(ctx, s); },
  },
  {
    name: "GIF: + opens add options",
    input: "select Evidence, drag onto Claim; click +",
    expected: "menu supports/opposes, flyout with Add existing… / Create new",
    setup: snapshot,
    run: async (ctx) => {
      const { fr, h } = await startAndDrag(ctx, "gif-plus", E, C);
      await h.hold(1.3);
      await h.click(await menuButton(ctx, "+"), { ms: 600, after: 0.8 });
      await h.moveTo(await menuButton(ctx, "Add existing…"), 450);
      await h.hold(1.0);
      await h.moveTo(await menuButton(ctx, "Create new"), 300);
      await h.hold(1.2);
      const o = await observe(ctx);
      return { frames: await finish(ctx, fr, 2), items: o.menuItems, flyout: o.flyout?.items };
    },
    expect: (o) => ({ pass: o.flyout?.length === 2, actual: `frames=${o.frames} menu=${o.items} flyout=${o.flyout}` }),
    teardown: async (ctx, s) => { await removeCursor(ctx); await restore(ctx, s); },
  },
  {
    name: "GIF: Add existing",
    input: "Claim → Question; Add existing…; pick informs; click informs",
    expected: "picker, toast, informs in menu, labelled arrow",
    setup: snapshot,
    run: async (ctx) => {
      const { fr, h } = await startAndDrag(ctx, "gif-add-existing", C, Q);
      await h.hold(1.0);
      await h.click(await menuButton(ctx, "Add existing…"), { ms: 550, after: 1.0 });
      await h.moveTo(await menuButton(ctx, "supports / is supported by"), 400);
      await h.moveTo(await menuButton(ctx, "informs / is informed by"), 450);
      await h.click(await menuButton(ctx, "informs / is informed by"), { ms: 150, after: 2.0 });
      await h.click(await menuButton(ctx, "informs"), { ms: 500, after: 0.4 });
      await sleep(400);
      await ctx.client.evaluate(`window.__dgEd.selectNone(); return true;`);
      const o = await observe(ctx);
      return { frames: await finish(ctx, fr, 3), arrow: o.arrow?.text, toasts: o.toasts };
    },
    expect: (o) => ({ pass: o.arrow === "informs", actual: `frames=${o.frames} arrow=${o.arrow} toasts=[${o.toasts}]` }),
    teardown: async (ctx, s) => { await removeCursor(ctx); await restore(ctx, s); },
  },
  {
    name: "GIF: Create new",
    input: `Claim → Question; Create new; type "${LABEL}" / "${COMPLEMENT}"; Blue; Continue; click ${LABEL}`,
    expected: "dialog filled at typing speed, both toasts, labelled blue arrow",
    setup: snapshot,
    run: async (ctx) => {
      const { fr, h } = await startAndDrag(ctx, "gif-create", C, Q);
      await h.hold(1.0);
      await h.click(await menuButton(ctx, "Create new"), { ms: 550, after: 0.3 });
      await ctx.client.waitFor(`!!${DIALOG}`, { label: "dialog" });
      await sleep(250);
      await h.hold(0.9);
      await h.click(await dialogEl(ctx, `return ${DIALOG}?.querySelectorAll("input[type=text]")[0];`), { ms: 550, after: 0.3 });
      await h.type(LABEL);
      await h.click(await dialogEl(ctx, `return ${DIALOG}?.querySelectorAll("input[type=text]")[1];`), { ms: 400, after: 0.3 });
      await h.type(COMPLEMENT);
      await h.hold(0.5);
      await h.click(await dialogEl(ctx, `return ${DIALOG}?.querySelector(".relative.min-w-32 > button");`), { ms: 450, after: 0.6 });
      await h.click(await dialogEl(ctx, colorOption(ctx, "Blue")), { ms: 450, after: 0.8 });
      await h.click(await dialogEl(ctx, `return [...(${DIALOG}?.querySelectorAll("button") ?? [])].find((b) => b.textContent.trim() === "Continue");`), { ms: 550, after: 0.2 });
      await sleep(500);
      await h.hold(2.2);
      await h.click(await menuButton(ctx, LABEL), { ms: 600, after: 0.4 });
      await sleep(400);
      await ctx.client.evaluate(`window.__dgEd.selectNone(); return true;`);
      const o = await observe(ctx);
      return { frames: await finish(ctx, fr, 3), arrow: `${o.arrow?.text}/${o.arrow?.color}`, toasts: o.toasts };
    },
    expect: (o) => ({ pass: o.arrow === `${LABEL}/blue`, actual: `frames=${o.frames} arrow=${o.arrow} toasts=[${o.toasts}]` }),
    teardown: async (ctx, s) => { await removeCursor(ctx); await restore(ctx, s); },
  },
];
EOF
} > $S/gifs.mjs; node --check $S/gifs.mjs && echo syntax-ok; grep -c 'const recorder' $S/gifs.mjs

